__NUXT_JSONP__("/por", (function(a,b,c,d,e){return {data:[{$axios:{request:{},getUri:{},delete:{},get:{},head:{},options:{},post:{},put:{},patch:{},defaults:{headers:{common:{Accept:"application\u002Fjson, text\u002Fplain, *\u002F*","accept-encoding":"gzip, deflate"},delete:{},get:{},head:{},post:{"Content-Type":"application\u002Fx-www-form-urlencoded"},put:{"Content-Type":"application\u002Fx-www-form-urlencoded"},patch:{"Content-Type":"application\u002Fx-www-form-urlencoded"}},baseURL:"http:\u002F\u002F52.198.144.187:81",transformRequest:[{}],transformResponse:[{}],timeout:0,adapter:{},xsrfCookieName:"XSRF-TOKEN",xsrfHeaderName:"X-XSRF-TOKEN",maxContentLength:-1,maxBodyLength:-1,validateStatus:{},transitional:{silentJSONParsing:true,forcedJSONParsing:true,clarifyTimeoutError:false}},interceptors:{request:{handlers:[{fulfilled:{},rejected:void 0,synchronous:false,runWhen:null}]},response:{handlers:[]}},CancelToken:{source:{}},isCancel:{},setBaseURL:{},setHeader:{},setToken:{},onRequest:{},onResponse:{},onRequestError:{},onResponseError:{},onError:{},create:{},$request:{},$delete:{},$get:{},$head:{},$options:{},$post:{},$put:{},$patch:{}},details:{slug:b,pageTitle:c,pageDescription:c,peopleChooseMli:{title:"3 razões pelas quais as pessoas escolhem MLI",subtitle:"(Mentor Language Institute)",lists:[{image:"\u002Fimages\u002Fhome\u002Fpor\u002Fpeople-choose-mli-1.jpg",title:"Hollywood & Westwood",description:"Estamos localizados em excelentes áreas populares de Los Angeles. Os estudantes não precisam apenas estudar inglês, mas também podem curtir Los Angeles.",read_more:[a]},{image:"\u002Fimages\u002Fhome\u002Fpor\u002Fpeople-choose-mli-2.jpg",title:"Aulas de manhã, de tarde e de noite",description:"Nós oferecemos aulas de manhã, tarde ou noite para pessoas que precisam de horários flexíveis.",read_more:[a]},{image:"\u002Fimages\u002Fhome\u002Fpor\u002Fpeople-choose-mli-3.jpg",title:"$201\u002F1 semana",description:"Boa localização e preço razoável! Compare nossos preços com outras escolas. Se você quiser informações de matrícula, clique em Contate-nos abaixo.",read_more:[a]}]},highlyRated:"\u002Fimages\u002Fhome\u002Fpor\u002Fmli-highly-rated.jpg",courses:{title:"Cursos",lists:[{image:d,title:"Programa ESL",subtitle:["Este programa é composto em ouvir\u002Ffalar, ler\u002Fvocabulário e aulas de gramática\u002Fescrita. O programa ESL é ideal para estudantes que desejam melhorar suas habilidades gerais de inglês."]},{image:e,title:"Programa TOEFL®",subtitle:["O programa TOEFL® da MLI é um exame intensivo das habilidades e estratégias necessárias para alcançar uma pontuação bem-sucedida nas quatro seções do Teste baseado na Internet (iBT)."]},{image:d,title:"Programa ESL de Férias",subtitle:["Este programa é composto por aulas de escuta\u002Fconversação, leitura\u002Fvocabulário e gramática\u002Fescrita. \u003Cbr\u003EOferecemos o programa Vacation ESL para estudantes que desejam estudar inglês por um curto período."]},{image:e,title:"IELTS™ Program",subtitle:["IELTS ™ é um teste, desenvolvido no Reino Unido e Austrália, para avaliar a proficiência do inglês dos alunos. Recentemente, muitas universidades americanas exigem uma pontuação no TOEFL® ou uma pontuação no IELTS ™.","O programa consiste em quatro partes: ouvir, falar, ler e escrever. Nesta classe, você aprenderá as habilidades \u002F estratégias para obter altos escores em cada seção.","IELTS ™ é dito ser relativamente mais fácil que o TOEFL®. É um programa perfeito para estudantes que acham o TOEFL® difícil."]},{image:"\u002Fimages\u002Ficons\u002Fmessage.png",title:"Programa de Conversação",subtitle:["Nosso programa concentra-se na aprimoração das habilidades de conversação em inglês, por meio de atividades envolventes e aprendizado interativo! Nas nossas aulas de conversação, os alunos exploram uma ampla variedade de vocabulário, expressões e idiomas que trazem vida às suas conversas. Aperfeiçoe sua pronúncia em nossa classe CMAR. Através de discussões estimulantes, simulações de situações e atividades em grupo, você ganhará confiança para se expressar e participar de conversas significativas. Nossos instrutores experientes proporcionam um ambiente de aprendizado de suporte, guiando você em uma jornada de descoberta da língua com maestria."]},{image:"\u002Fimages\u002Ficons\u002Fsuitcase.png",title:"Negócios ＋ TOEIC®",subtitle:["O teste TOEIC® é um indicador da proficiência em inglês em negócios e é usado por várias empresas e organizações em todo o mundo. Além do curso de negócios padrão, o curso TOEIC® prepara os alunos para o sucesso no TOEIC® - Exame de leitura e audição, introduzindo vocabulário essencial e explorando estratégias para alcançar uma alta pontuação no teste.","Este curso será útil para melhorar suas habilidades de inglês, como vocabulário, leitura, escuta e gramática. Ao aprender as estratégias para encontrar respostas corretas, você poderá obter uma pontuação elevada."]}]},schedule:"\u002Fimages\u002Fhome\u002Fpor\u002Ffree_trial_banner_por.png",link:"\u002Fpor\u002Ffreetrial",partnerSchools:{title:"MLI's Partner Universities \u002F Colleges",subtitle:"\"MLI students can enroll at partner universities or colleges after completing certain MLI programs.\""},locationCampus:{title:"Localização \u002F Campus",lists:[{image:"\u002Fimages\u002Fhome\u002Flocation-campus-1.jpg",title:"Campus de Westwood",subtitle:"Westwood é um bairro vibrante e único localizado no lado oeste de Los Angeles. Westwood é famoso por ser a casa da UCLA. É uma área muito divertida e popular para os alunos, uma vez que há muitos estudantes universitários e muitas lojas, restaurantes e lugares seguros para sair.",read_more:["\u003Ca href=\"\u002Fpor\u002Fwestwood\u002F\"\u003E» CONSULTE MAIS INFORMAÇÃO\u003C\u002Fa\u003E"]},{image:"\u002Fimages\u002Fhome\u002Flocation-campus-2.jpg",title:"Campus de Hollywood",subtitle:"O campus de Hollywood está ao lado do famoso Teatro chinês. Existem salas de cinema famosas, bons restaurantes, lojas e boates na área de Hollywood e esta área é sempre um lugar muito animado.",read_more:["\u003Ca href=\"\u002Fpor\u002Fhollywood\u002F\"\u003E» CONSULTE MAIS INFORMAÇÃO\u003C\u002Fa\u003E"]}]},testimonials:{title:"Depoimentos de alunos",seemoreBtn:"Ver mais",TestimonialLink:"\u002Fpor\u002Ftestimonials",readmoreBtn:"Leia mais"},dir:"\u002Fhome",path:"\u002Fhome\u002Fpor",extension:".json",createdAt:"2026-10-22T16:31:29.602Z",updatedAt:"2025-05-26T12:06:27.785Z"},lang:b}],fetch:{},mutations:void 0}}("\u003Ca href=\"\u002Fpor\u002Ffeature\u002F\"\u003E» CONSULTE MAIS INFORMAÇÃO\u003C\u002Fa\u003E","por","Intercâmbio com melhor custo-benefício em Los Angeles | Mentor Language Institute","\u002Fimages\u002Ficons\u002Fpaste.png","\u002Fimages\u002Ficons\u002Fpen.png")));